/* =========================================================
   Website Ucapan Ulang Tahun — Adik Tersayang
   Tema: Elegan | File ini: semua interaksi & animasi
   ========================================================= */
(function () {
  "use strict";

  var $ = function (id) { return document.getElementById(id); };
  var main = $("main");
  var cover = $("cover");
  var fx = $("fx");

  /* ===================================
     1) BACKGROUND: bintang berkelip + debu emas mengambang
  ==================================== */
  var canvas = $("bgCanvas");
  var ctx = canvas.getContext("2d");
  var W = 0, H = 0, dpr = 1;
  var stars = [], dust = [];

  function ukur() {
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    W = window.innerWidth;
    H = window.innerHeight;
    canvas.width = W * dpr;
    canvas.height = H * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    var banyak = Math.round((W * H) / 14000);
    stars = Array.from({ length: Math.max(40, banyak) }, function () {
      return {
        x: Math.random() * W,
        y: Math.random() * H,
        r: 0.4 + Math.random() * 1.3,
        fase: Math.random() * Math.PI * 2,
        kcp: 0.4 + Math.random() * 1.2,
        emas: Math.random() < 0.4
      };
    });
    dust = Array.from({ length: Math.round(W / 26) }, function () {
      return {
        x: Math.random() * W,
        y: Math.random() * H,
        r: 0.6 + Math.random() * 1.4,
        vy: -(0.12 + Math.random() * 0.3),
        vx: (Math.random() - 0.5) * 0.22,
        fase: Math.random() * Math.PI * 2
      };
    });
  }

  function gambar(t) {
    ctx.clearRect(0, 0, W, H);

    // bintang berkelip
    for (var i = 0; i < stars.length; i++) {
      var s = stars[i];
      var alfa = 0.25 + 0.6 * (0.5 + 0.5 * Math.sin(t * 0.001 * s.kcp + s.fase));
      ctx.globalAlpha = alfa;
      if (s.emas) ctx.fillStyle = "#e8c97a"; else ctx.fillStyle = "#ffffff";
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fill();
    }

    // debu emas naik perlahan
    ctx.globalCompositeOperation = "lighter";
    for (var j = 0; j < dust.length; j++) {
      var d = dust[j];
      d.y += d.vy;
      d.x += d.vx + Math.sin(t * 0.0006 + d.fase) * 0.12;
      if (d.y < -6) { d.y = H + 6; d.x = Math.random() * W; }
      if (d.x < -6) d.x = W + 6;
      if (d.x > W + 6) d.x = -6;
      ctx.globalAlpha = 0.12 + 0.25 * (0.5 + 0.5 * Math.sin(t * 0.002 + d.fase));
      ctx.fillStyle = "#f2d98b";
      ctx.beginPath();
      ctx.arc(d.x, d.y, d.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalCompositeOperation = "source-over";
    ctx.globalAlpha = 1;

    requestAnimationFrame(gambar);
  }

  window.addEventListener("resize", ukur);
  ukur();
  requestAnimationFrame(gambar);

  /* ===================================
     2) EFEK: kembang api bintang + confetti + percikan
  ==================================== */
  var PARTIKEL = {
    emas: ["#f0d98f", "#d4af37", "#fdf6e0"],
    campur: ["#e8c97a", "#fdf6e0", "#c98ba6", "#9fb6ff", "#ffd98b"]
  };

  function sembur(x, y, opts) {
    opts = opts || {};
    var n = opts.n || 26;
    var warna = opts.warna || PARTIKEL.emas;
    var tipe = opts.tipe || "konfeti";
    var besar = opts.besar !== undefined ? opts.besar : 7;

    for (var i = 0; i < n; i++) {
      (function () {
        var p = document.createElement("div");
        p.className = "partikel pn-" + tipe;
        if (tipe !== "api" && tipe !== "bulat") p.style.background = warna[i % warna.length];
        p.style.left = (x + Math.random() * 8 - 4) + "px";
        p.style.top = (y + Math.random() * 8 - 4) + "px";
        if (tipe === "konfeti") {
          p.style.width = (besar * (0.5 + Math.random())) + "px";
          p.style.height = (besar * 0.4 * (0.5 + Math.random())) + "px";
        } else {
          p.style.width = (besar * (0.6 + Math.random())) + "px";
          p.style.height = p.style.width;
        }
        fx.appendChild(p);

        var sudut = Math.random() * Math.PI * 2;
        var laju = 1.6 + Math.random() * (tipe === "konfeti" ? 6.5 : 5);
        var vx = Math.cos(sudut) * laju;
        var vy = Math.sin(sudut) * laju - (tipe === "konfeti" ? 4 : 2.4);
        var putar = (Math.random() - 0.5) * 720;
        var umur = 1100 + Math.random() * 700;
        var tAwal = performance.now();

        (function langkah() {
          var dt = performance.now() - tAwal;
          var prog = dt / umur;
          if (prog >= 1) { p.remove(); return; }
          vx *= 0.985;
          vy += (tipe === "confetti" || tipe === "konfeti") ? 0.30 : 0.12;
          p.style.transform = "translate(" + (vx * dt / 16) + "px," + (vy * dt / 16) + "px) rotate(" + (putar * dt / 1000) + "deg)";
          p.style.opacity = (1 - prog).toFixed(3);
          requestAnimationFrame(langkah);
        })();
      })();
    }
  }

  function kembangApiBintang(x, y) {
    var n = 14;
    for (var i = 0; i < n; i++) {
      (function () {
        var b = document.createElement("div");
        b.className = "bintang-api";
        b.style.left = x + "px";
        b.style.top = y + "px";
        fx.appendChild(b);
        var sudut = (i / n) * Math.PI * 2;
        var jarak = 70 + Math.random() * 40;
        var dur = 900 + Math.random() * 400;
        var tAwal = performance.now();
        (function langkah() {
          var prog = (performance.now() - tAwal) / dur;
          if (prog >= 1) { b.remove(); return; }
          var e = 1 - (1 - prog) * (1 - prog); // ease-out
          b.style.transform =
            "translate(" + (Math.cos(sudut) * jarak * e) + "px," +
            (Math.sin(sudut) * jarak * e - 30 * e) + "px) scale(" + (1 - prog * 0.6) + ")";
          b.style.opacity = (1 - prog).toFixed(3);
          requestAnimationFrame(langkah);
        })();
      })();
    }
  }

  function loncatanAir(fa) {
    var posLilin = $("candles").getBoundingClientRect();
    sembur(posLilin.left + fa.offsetLeft + 10, posLilin.top + fa.offsetTop, { n: 18, warna: PARTIKEL.emas, tipe: "konfeti", besar: 6 });
  }

  /* ===================================
     3) HALAMAN PEMBUKA "BUKA KEJUTAN"
  ==================================== */
  var dibuka = false;

  function bukaKejutan() {
    if (dibuka) return;
    dibuka = true;
    cover.classList.add("kabur");
    main.setAttribute("aria-hidden", "false");
    setTimeout(function () { cover.style.display = "none"; }, 950);

    // kembang api beruntun di layar
    var titik = [
      { x: 0.30, y: 0.30 }, { x: 0.70, y: 0.25 }, { x: 0.50, y: 0.45 },
      { x: 0.22, y: 0.60 }, { x: 0.78, y: 0.58 }, { x: 0.42, y: 0.75 },
      { x: 0.62, y: 0.80 }
    ];
    titik.forEach(function (p, i) {
      setTimeout(function () {
        kembangApiBintang(p.x * W, p.y * H);
        sembur(p.x * W, p.y * H, { n: 34, warna: PARTIKEL.campur, tipe: "api", besar: 8 });
      }, 350 + i * 320);
    });

    mulaiMengetik();
    mulaiMusik();
  }

  $("btnBuka").addEventListener("click", bukaKejutan);
  document.addEventListener("keydown", function (e) {
    if (e.key === "Enter" && cover.style.display !== "none") bukaKejutan();
  });

  /* ===================================
     4) ANIMASI TEKS MENGETIK
  ==================================== */
  var kalimat = [
    "Semoga bertambahnya usia diiringi bertambahnya kebahagiaan.",
    "Semoga impian-impianmu satu per satu jadi nyata.",
    "Terima kasih sudah jadi sosok yang penyayang dan kuat.",
    "Selamat ulang tahun, Adik Tersayang!",
    "Tetaplah jadi kamu yang sekarang. Kami selalu di sini. %u2661"
  ];
  var eleTik = $("typedLine");

  function tidur(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

  async function mulaiMengetik() {
    await tidur(500);
    for (var g = 0; g < kalimat.length; g++) {
      var k = kalimat[g].replace("%u2661", "\u2661");
      eleTik.textContent = "";
      var caret = document.createElement("span");
      caret.className = "t-caret";
      for (var c = 0; c < k.length; c++) {
        eleTik.textContent = k.slice(0, c + 1);
        eleTik.appendChild(caret);
        await tidur(38);
      }
      await tidur(2200);
      if (g < kalimat.length - 1) {
        for (var h = k.length; h > 0; h--) {
          eleTik.textContent = k.slice(0, h - 1);
          eleTik.appendChild(caret);
          await tidur(14);
        }
        await tidur(350);
      }
    }
  }

  /* ===================================
     5) KUE & LILIN BISA DITIUP
  ==================================== */
  var isLilin = [];
  var jml = 3;

  (function buatLilin() {
    var wadah = $("candles");
    for (var i = 0; i < jml; i++) {
      var c = document.createElement("div");
      c.className = "candle";
      c.setAttribute("role", "button");
      c.setAttribute("tabindex", "0");
      c.innerHTML =
        '<div class="flame"></div>' +
        '<div class="wick"></div>' +
        '<div class="candle-body"></div>';
      wadah.appendChild(c);
      isLilin.push(false);

      (function (el) {
        function padam() {
          if (el.classList.contains("padam")) return;
          el.classList.add("padam");
          var tiga;
          for (tiga = 0; tiga < 3; tiga++) {
            var s = document.createElement("div");
            s.className = "smoke";
            s.style.animationDelay = (tiga * 0.22) + "s";
            el.appendChild(s);
            setTimeout(function (n) { n.remove(); }, 1900);
          }
          loncatanAir(el);
          isLilin[el.dataset.i] = true;
          cekSemuaPadam();
        }
        el.addEventListener("click", padam);
        el.addEventListener("keydown", function (e) {
          if (e.key === "Enter" || e.key === " ") { e.preventDefault(); padam(); }
        });
      })(c, i);
    }
    wadah.querySelectorAll(".candle").forEach(function (el, idx) { el.dataset.i = idx; });
  })();

  var pesanLilin = $("cakeMsg");
  var btnReset = $("btnResetLilin");
  var semuaPadam = false;

  function cekSemuaPadam() {
    var mati = isLilin.filter(Boolean).length;
    if (mati > 0 && btnReset.hidden) btnReset.hidden = false;
    if (mati === jml && !semuaPadam) {
      semuaPadam = true;
      pesanLilin.textContent = "Semoga semua keinginanmu terkabul sekarang ya!";
      pesanLilin.classList.add("muncul");
      var box = $("cakeScene").getBoundingClientRect();
      kembangApiBintang(box.left + box.width / 2, box.top + 40);
      sembur(box.left + box.width / 2, box.top + 40, { n: 30, warna: PARTIKEL.emas, tipe: "api", besar: 7 });
    }
  }

  btnReset.addEventListener("click", function () {
    isLilin = isLilin.map(function () { return false; });
    semuaPadam = false;
    pesanLilin.classList.remove("muncul");
    btnReset.hidden = true;
    $("candles").querySelectorAll(".candle").forEach(function (c) {
      c.classList.remove("padam");
      c.querySelectorAll(".smoke").forEach(function (n) { n.remove(); });
    });
  });

  /* ===================================
     6) GALERI FOTO (maks 3) + SLIDER
  ==================================== */
  var track = $("track");
  var dots = $("dots");
  var fotoInput = $("fotoInput");
  var statusFoto = $("fotoStatus");
  var foto = [];                // dataURL (hasil kompresi, siap disimpan)
  var fotoFolder = [];          // foto yang diambil otomatis dari folder "foto/"
  var idx = 0;
  var maxFoto = 4;
  var timerAuto = null;
  var kunciFoto = "fotoUlangTahun";
  var dapatSimpan = true;
  var namaFolder = ["foto 1", "foto 2", "foto 3", "foto 4"];
  var ekstensiFoto = ["jpg", "jpeg"];

  // Foto bawaan yang sudah tertanam di dalam kode (diisi otomatis dari
  // folder "foto/" saat website "di-pasarkan"/dibagikan).
  var FOTO_BAWAAN = [
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,"
  ]

  var totalFoto = function () { return FOTO_BAWAAN.length + fotoFolder.length + foto.length; };

  // muat foto yang sudah dipilih & disimpan sebelumnya
  try {
    var tersimpan = localStorage.getItem(kunciFoto);
    if (tersimpan) {
      var arr = JSON.parse(tersimpan);
      if (Array.isArray(arr)) foto = arr.map(String).filter(function (x) { return x && x.length > 0; });
    }
  } catch (e) {}

  // kompres foto ke maks ~1200px supaya ringan & muat disimpan
  function kompresFoto(berkas) {
    return new Promise(function (selesai, gagal) {
      var r = new FileReader();
      r.onload = function () {
        var img = new Image();
        img.onload = function () {
          var MAX = 1200;
          var skala = Math.min(1, MAX / Math.max(img.width, img.height));
          var w = Math.round(img.width * skala);
          var h = Math.round(img.height * skala);
          var cv = document.createElement("canvas");
          cv.width = w;
          cv.height = h;
          var cp = cv.getContext("2d");
          cp.fillStyle = "#ffffff";
          cp.fillRect(0, 0, w, h);
          cp.drawImage(img, 0, 0, w, h);
          selesai(cv.toDataURL("image/jpeg", 0.82));
        };
        img.onerror = gagal;
        img.src = r.result;
      };
      r.onerror = gagal;
      r.readAsDataURL(berkas);
    });
  }

  // simpan foto ke penyimpanan browser agar tidak hilang saat halaman ditutup
  function simpanFoto() {
    if (!dapatSimpan) return false;
    try {
      localStorage.setItem(kunciFoto, JSON.stringify(foto));
      return true;
    } catch (e) {
      dapatSimpan = false;
      statusFoto.textContent = "Penyimpanan penuh: foto tetap tampil selama halaman dibuka, tapi tidak tersimpan permanen.";
      return false;
    }
  }

  // cari foto di folder "foto/" dengan nama foto1..foto3 (atau "foto 1".."foto 3")
  function cekFotoFolder() {
    // foto sudah tertanam di kode -> tidak perlu dicek folder lagi
    if (FOTO_BAWAAN.length > 0) return Promise.resolve([]);
    var janji = [];
    namaFolder.forEach(function (nama, i) {
      janji.push(new Promise(function (selesai) {
        var coba = ekstensiFoto.slice();
        (function cobaBerikut() {
          if (!coba.length) { selesai(null); return; }
          var ext = coba.shift();
          var gj = new Image();
          gj.onload = function () { fotoFolder[i] = gj.src; selesai(gj.src); };
          gj.onerror = function () { cobaBerikut(); };
          gj.src = "foto/" + nama + "." + ext;
        })();
      }));
    });
    return Promise.all(janji);
  }

  function perbaruiStatus() {
    var btnHapus = $("btnHapusFoto");
    var btnUnduh = $("btnUnduhFoto");
    var total = totalFoto();
    if (total === 0) {
      statusFoto.textContent = "Belum ada foto. Taruh foto JPEG ke folder foto/ (foto 1.jpg–foto 4.jpg) atau pilih lewat tombol di atas.";
      btnHapus.hidden = true;
      btnUnduh.hidden = true;
    } else {
      var pesan = "Foto tersimpan otomatis (" + total + " foto).";
      if (FOTO_BAWAAN.length > 0) pesan += " | " + FOTO_BAWAAN.length + " foto sudah tertanam di dalam kode website.";
      else if (fotoFolder.length > 0) pesan += " | " + fotoFolder.length + " foto dari folder foto/.";
      statusFoto.textContent = pesan;
      btnHapus.hidden = foto.length === 0;
      btnUnduh.hidden = false;
    }
  }

  var slideDefault = [
    { tipe: "ph", kelas: "ph-1", judul: "Awal mula kita", sub: "pertemuan yang tak terduga" },
    { tipe: "ph", kelas: "ph-2", judul: "Tawa & cerita", sub: "hari-hari penuh warna" },
    { tipe: "ph", kelas: "ph-3", judul: "Hingga nanti", sub: "untuk perjalanan yang panjang" }
  ];

  var ikonSpark = '<svg viewBox="0 0 24 24" width="34" height="34"><path d="M12 2l2.4 7.2L22 12l-7.6 2.8L12 22l-2.4-7.2L2 12l7.6-2.8z" fill="#e8c97a"/></svg>';

  function dataSetGlobal() {
    var daftar = [];
    FOTO_BAWAAN.forEach(function (src) {
      daftar.push({ tipe: "img", src: src });
    });
    fotoFolder.forEach(function (src) {
      daftar.push({ tipe: "img", src: src });
    });
    foto.forEach(function (src) {
      daftar.push({ tipe: "img", src: src });
    });
    slideDefault.forEach(function (s) {
      daftar.push({ tipe: "ph", kelas: s.kelas, judul: s.judul, sub: s.sub });
    });
    return daftar;
  }

  function bangunDots(n) {
    dots.innerHTML = "";
    for (var i = 0; i < n; i++) {
      (function (g) {
        var b = document.createElement("button");
        b.type = "button";
        b.setAttribute("aria-label", "Ke slide " + (g + 1));
        b.addEventListener("click", function () { pindah(g); });
        dots.appendChild(b);
      })(i);
    }
  }

  function render() {
    var daftar = dataSetGlobal();
    track.innerHTML = "";
    daftar.forEach(function (s) {
      var d = document.createElement("div");
      d.className = "slide";
      if (s.tipe === "img") {
        var img = document.createElement("img");
        img.src = s.src;
        img.alt = "Foto kenangan";
        d.appendChild(img);
      } else {
        d.className += " " + s.kelas;
        d.innerHTML = '<div class="ph">' + ikonSpark +
          '<p class="ph-txt">' + s.judul + '</p>' +
          '<p class="ph-sub">' + s.sub + '</p></div>';
      }
      track.appendChild(d);
    });
    idx = Math.min(idx, daftar.length - 1);
    bangunDots(daftar.length);
    aturTransisi(daftar.length);
    updateDots();
  }

  function aturTransisi(n) {
    track.style.transform = "translateX(-" + (idx * 100) + "%)";
    $("navPrev").style.display = n > 1 ? "" : "none";
    $("navNext").style.display = n > 1 ? "" : "none";
  }

  function pindah(g) {
    var n = dataSetGlobal().length;
    if (n === 0) return;
    if (g < 0) g = n - 1;
    if (g > n - 1) g = 0;
    idx = g;
    aturTransisi(n);
    updateDots();
    resetAuto();
  }

  function updateDots() {
    var tombol = dots.querySelectorAll("button");
    tombol.forEach(function (b, i) {
      b.classList.toggle("aktif", i === idx);
    });
  }

  function resetAuto() {
    clearInterval(timerAuto);
    timerAuto = setInterval(function () {
      if (dibuka) pindah(idx + 1);
    }, 4500);
  }

  $("navPrev").addEventListener("click", function () { pindah(idx - 1); });
  $("navNext").addEventListener("click", function () { pindah(idx + 1); });

  var sliderEl = $("slider");
  sliderEl.addEventListener("mouseenter", function () { clearInterval(timerAuto); });
  sliderEl.addEventListener("mouseleave", resetAuto);

  fotoInput.addEventListener("change", function () {
    var files = Array.prototype.slice.call(fotoInput.files || []);
    var gambarPilih = files.filter(function (f) { return f.type && f.type.indexOf("image/") === 0; });
    var sisa = Math.max(0, maxFoto - totalFoto());
    var pakai = gambarPilih.slice(0, sisa);
    if (gambarPilih.length > sisa) {
      statusFoto.textContent = "Lebih dari " + maxFoto + " foto. Slot yang tersisa hanya " + sisa + ".";
    }
    pakai.forEach(function (f) {
      kompresFoto(f).then(function (dataUrl) {
        foto.push(dataUrl);
        render();
        if (simpanFoto()) perbaruiStatus();
      }).catch(function () {
        statusFoto.textContent = "Ada foto yang gagal dibaca, coba pilih yang lain.";
      });
    });
    fotoInput.value = "";
  });

  $("btnHapusFoto").addEventListener("click", function () {
    foto = [];
    idx = 0;
    try { localStorage.removeItem(kunciFoto); } catch (e) {}
    perbaruiStatus();
    render();
  });

  // Simpan SEMUA foto (bawaan + folder + hasil unggah) ke dalam script.js
  // agar bisa dibagikan: ganti script.js lama dengan hasil unduhan ini.
  var SRC_KU = document.currentScript ? document.currentScript.textContent : "";

  $("btnUnduhFoto").addEventListener("click", function () {
    var daftar = [];
    FOTO_BAWAAN.forEach(function (x) { daftar.push(x); });
    fotoFolder.forEach(function (x) { daftar.push(x); });
    foto.forEach(function (x) { daftar.push(x); });
    if (daftar.length === 0) { statusFoto.textContent = "Belum ada foto untuk disimpan."; return; }

    var json = JSON.stringify(daftar);
    var isi;
    var pola = /var FOTO_BAWAAN = \[[\s\S]*?\];/;
    if (SRC_KU && pola.test(SRC_KU)) {
      isi = SRC_KU.replace(pola, "var FOTO_BAWAAN = " + json + ";");
    } else {
      statusFoto.textContent = "Tidak bisa membaca kode script.js. Buka website langsung dari file index.html.";
      return;
    }

    var blob = new Blob([isi], { type: "text/javascript;charset=utf-8" });
    var a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = "script.js";
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { URL.revokeObjectURL(a.href); }, 4000);
    statusFoto.textContent = "script.js (dengan semua foto) berhasil diunduh. Ganti script.js lama di folder dengan file baru ini, lalu share kembali folder website.";
  });

  perbaruiStatus();
  render();
  resetAuto();

  // muat foto dari folder "foto/" saat halaman dibuka
  cekFotoFolder().then(function () {
    fotoFolder = fotoFolder.filter(function (x) { return !!x; });
    perbaruiStatus();
    render();
    resetAuto();
  });

  /* ===================================
     7) MUSIK LATAR: lagu.mp3 + cadangan melodi built-in
  ==================================== */
  var audio = $("audioLagu");
  var btnM = $("btnMusic");
  var gunaSynth = false;
  var playing = false;

  var audioCtx = null, gainMaster = null, osil = null, waktuStart = 0;

  var NOTA = {
    G4: 392.00, A4: 440.00, B4: 493.88, C5: 523.25, D5: 587.33, E5: 659.26, F5: 698.46, G5: 783.99
  };
  // Melodi "Happy Birthday" : [nota, ketukan]
  var MELODI = [
    "G4/1", "G4/0.5", "A4/1", "G4/1", "C5/1", "B4/2",
    "G4/1", "G4/0.5", "A4/1", "G4/1", "D5/1", "C5/2",
    "G4/1", "G4/0.5", "G5/1", "E5/1", "C5/1", "B4/1", "A4/2.2",
    "F5/1", "F5/0.5", "E5/1", "C5/1", "D5/1", "C5/2.4"
  ];

  function nyalakanSynth() {
    if (!audioCtx) {
      var AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return false;
      audioCtx = new AC();
      gainMaster = audioCtx.createGain();
      gainMaster.gain.value = 0.28;
      gainMaster.connect(audioCtx.destination);
    }
    if (audioCtx.state === "suspended") audioCtx.resume();
    waktuStart = audioCtx.currentTime + 0.05;
    var beat = 0.42;
    MELODI.forEach(function (data) {
      var pecah = data.split("/");
      var not = NOTA[pecah[0]];
      var dur = parseFloat(pecah[1]) * beat;
      var o = audioCtx.createOscillator();
      var g = audioCtx.createGain();
      o.type = "triangle";
      o.frequency.value = not;
      o.connect(g);
      g.connect(gainMaster);
      var t = waktuStart;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(1, t + 0.02);
      g.gain.exponentialRampToValueAtTime(0.001, t + dur * 0.95);
      o.start(t);
      o.stop(t + dur);
      waktuStart += dur;
    });
    return true;
  }

  function setIkon() {
    $("iconPlayOn").hidden = playing;
    $("iconPlayOff").hidden = !playing;
    btnM.setAttribute("aria-pressed", String(playing));
  }

  function mulaiMusik() {   // dipanggil setelah klik "Buka Kejutan"
    cobaPlay();
  }

  function gotoDiam() {
    playing = false;
    if (audio.paused === false) audio.pause();
    if (gainMaster && audioCtx) {
      try { gainMaster.gain.setValueAtTime(0.0001, audioCtx.currentTime); } catch (e) {}
    }
    setIkon();
  }

  function cobaPlay() {
    if (playing) { gotoDiam(); return; }

    var p = audio.play();
    if (p && typeof p.then === "function") {
      p.then(function () {
        gunaSynth = false;
        playing = true;
        setIkon();
      }).catch(function () {
        // file lagu.mp3 tidak ada / gagal dimuat -> pakai melodi built-in
        if (!gunaSynth) gunaSynth = nyalakanSynth();
        else if (gainMaster) gainMaster.gain.setValueAtTime(0.28, audioCtx.currentTime);
        playing = true;
        setIkon();
      });
    } else {
      // browser lama (play() tanpa promise)
      audio.onplaying = function () { playing = true; setIkon(); };
      audio.onerror = function () {
        if (!gunaSynth) gunaSynth = nyalakanSynth();
        playing = true;
        setIkon();
      };
    }
  }

  btnM.addEventListener("click", cobaPlay);
  audio.addEventListener("ended", function () { playing = false; setIkon(); });

  /* ===================================
     8) PESAN PERSONAL — bisa diedit + tersimpan
  ==================================== */
  var kontenPesan = $("pesanKonten");
  var cPesan = kontenPesan.innerHTML;   // pesan bawaan (default)
  var btnEdit = $("btnEditPesan");
  var btnSimpan = $("btnSimpanPesan");
  var btnResetPesan = $("btnResetPesan");

  // muat pesan tersimpan (kalau ada)
  try {
    var simpanan = localStorage.getItem("pesanUlangTahun");
    if (simpanan) kontenPesan.innerHTML = simpanan;
  } catch (e) {}

  btnEdit.addEventListener("click", function () {
    kontenPesan.contentEditable = "true";
    kontenPesan.classList.add("mengetik");
    kontenPesan.focus();
    btnEdit.hidden = true;
    btnSimpan.hidden = false;
    btnResetPesan.hidden = false;
  });

  btnSimpan.addEventListener("click", function () {
    kontenPesan.contentEditable = "false";
    kontenPesan.classList.remove("mengetik");
    btnEdit.hidden = false;
    btnSimpan.hidden = true;
    btnResetPesan.hidden = true;
    try { localStorage.setItem("pesanUlangTahun", kontenPesan.innerHTML); } catch (e) {}
  });

  btnResetPesan.addEventListener("click", function () {
    kontenPesan.innerHTML = cPesan;
    btnSimpan.click();
    btnResetPesan.hidden = true;
  });

  /* ===================================
     9) MUNCULKAN SEKSI SAAT DI-SCROLL
  ==================================== */
  if ("IntersectionObserver" in window) {
    var obs = new IntersectionObserver(function (entri) {
      entri.forEach(function (e) {
        if (e.isIntersecting) {
          e.target.classList.add("lihat");
          obs.unobserve(e.target);
        }
      });
    }, { threshold: 0.18 });
    document.querySelectorAll(".sec").forEach(function (s) { obs.observe(s); });
  } else {
    document.querySelectorAll(".sec").forEach(function (s) { s.classList.add("lihat"); });
  }
})();